import sys
from functools import lru_cache


def solve_case(a: str, b: str) -> int:
    """A、B 各自保序归并成 C，返回所有 C 的最长回文子串长度的最大值。"""
    la, lb = len(a), len(b)

    @lru_cache(maxsize=None)
    def ok(i: int, j: int, k: int, l: int) -> bool:
        # A[i:j] 与 B[k:l] 拼起来是否为回文（左闭右开，允许其中一段为空）
        n = (j - i) + (l - k)
        if n <= 1:
            return True          # 空串与单字符都是回文（基例）
        if j - i >= 2 and a[i] == a[j - 1] and ok(i + 1, j - 1, k, l):
            return True          # 最外层一对都取自 A，必须各用 A 的一个字符
        if j - i >= 1 and l - k >= 1 and a[i] == b[l - 1] and ok(i + 1, j, k, l - 1):
            return True          # 左端取自 A、右端取自 B
        if j - i >= 1 and l - k >= 1 and b[k] == a[j - 1] and ok(i, j - 1, k + 1, l):
            return True          # 左端取自 B、右端取自 A
        if l - k >= 2 and b[k] == b[l - 1] and ok(i, j, k + 1, l - 1):
            return True          # 最外层一对都取自 B，必须各用 B 的一个字符
        return False

    best = 0
    for i in range(la + 1):
        for j in range(i, la + 1):
            for k in range(lb + 1):
                for l in range(k, lb + 1):
                    if (j - i) + (l - k) > best and ok(i, j, k, l):
                        best = (j - i) + (l - k)
    ok.cache_clear()
    return best


def main() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    t = int(data[0])
    pos = 1
    out = []
    for _ in range(t):
        a = data[pos] if pos < len(data) else ''
        b = data[pos + 1] if pos + 1 < len(data) else ''
        pos += 2
        out.append(str(solve_case(a, b)))
    sys.stdout.write('\n'.join(out) + '\n')


if __name__ == '__main__':
    main()
